let openTaskSwipeId=null;let previewWelcome=new URLSearchParams(location.search).has('welcome');let pageMotion=false,celebrateTaskId=null;
const dateKey=date.toLocaleDateString('sv-SE');
let migrated=false;const starterTaskNames=new Set(['Выпить воду','Сделать зарядку','Учёба / Работа','Прочитать 10 страниц','Вечерняя рутина','Покормить морских свинок']);const isStarterTask=t=>starterTaskNames.has(t.name)&&[1,2,3,4,5,6].includes(Number(t.id));state.tasks=Array.isArray(state.tasks)?state.tasks:[];const cleanedTemplates=state.tasks.filter(t=>!isStarterTask(t));if(cleanedTemplates.length!==state.tasks.length){state.tasks=cleanedTemplates;migrated=true}state.plans=state.plans||{};state.dayTypes=state.dayTypes||{};Object.entries(state.plans).forEach(([day,items])=>{if(!Array.isArray(items)){state.plans[day]=[];migrated=true;return}const cleaned=items.filter(t=>!isStarterTask(t));if(cleaned.length!==items.length){state.plans[day]=cleaned;migrated=true}});if(!state.plans[dateKey]){state.plans[dateKey]=state.tasks.map(t=>({...t}));migrated=true}state.selectedDate=state.selectedDate||dateKey;state.plans[state.selectedDate]=state.plans[state.selectedDate]||[];if(state.page==='calendar'&&!state.calendarOrigin){state.calendarOrigin=dateKey;migrated=true}if(state.page==='rewards'){state.page='garden';migrated=true}if(migrated)localStorage.setItem(KEY,JSON.stringify(state));
state.reminders={daily:false,time:'20:00',items:[],days:[],...state.reminders};state.reminders.items=state.reminders.items||[];state.reminders.days=state.reminders.days||[];
function currentTasks(){return state.plans[state.selectedDate]||(state.plans[state.selectedDate]=[])}
function dateObject(key){let [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d)}
function formatDate(key,opts={day:'numeric',month:'long',year:'numeric'}){return dateObject(key).toLocaleDateString('ru-RU',opts)}
function syncAndroidPlannerNotifications(){const native=window.PlannerAndroidNotifications;if(!native)return;const now=Date.now();[...(state.reminders.items||[]),...(state.reminders.days||[])].forEach(item=>{if(!item.sent&&new Date(`${item.date}T${item.time}:00`).getTime()<=now)item.sent=true});localStorage.setItem(KEY,JSON.stringify(state));native.sync(state.reminders,state.plans).catch(()=>{})}
function save(){localStorage.setItem(KEY,JSON.stringify(state));syncReminderTimer();syncAndroidPlannerNotifications()}
let reminderTimer;
function syncReminderTimer(){clearTimeout(reminderTimer);if(!state?.reminders||typeof Notification==='undefined'||Notification.permission!=='granted')return;const now=Date.now(),jobs=[];if(state.reminders.daily){let d=new Date();const [h,m]=state.reminders.time.split(':').map(Number);d.setHours(h,m,0,0);if(d.getTime()<=now)d.setDate(d.getDate()+1);jobs.push({at:d.getTime(),daily:true})}state.reminders.items.forEach(x=>{if(!x.sent){const d=new Date(`${x.date}T${x.time}:00`);if(d.getTime()>now)jobs.push({at:d.getTime(),item:x})}});state.reminders.days.forEach(x=>{if(!x.sent){const d=new Date(`${x.date}T${x.time}:00`);if(d.getTime()>now)jobs.push({at:d.getTime(),item:x,plan:true})}});if(!jobs.length)return;jobs.sort((a,b)=>a.at-b.at);reminderTimer=setTimeout(async()=>{if(Date.now()+250<jobs[0].at){syncReminderTimer();return}const job=jobs[0];if(job.daily){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const key=tomorrow.toLocaleDateString('sv-SE'),count=(state.plans[key]||[]).length;await showPlannerNotice('Твой план на завтра',count?`В списке ${count} ${count===1?'маленькое дело':'маленьких дел'}. Загляни в планер ♡`:'Загляни в планер и выбери доброе дело для себя ♡')}else if(job.plan){const count=(state.plans[job.item.date]||[]).length;await showPlannerNotice('План на выбранный день',count?'Сегодня в плане есть маленькие дела ♡':'Открой планер и выбери маленькое дело для себя ♡');job.item.sent=true;save()}else{const task=(state.plans[job.item.date]||[]).find(t=>String(t.id)===String(job.item.taskId));await showPlannerNotice('Время для маленького шага ♡',task?.name||job.item.name);job.item.sent=true;save()}syncReminderTimer()},Math.min(Math.max(0,jobs[0].at-now),2147480000))}
async function showPlannerNotice(title,body){try{const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:new URL('icons/app-icon-192.png',reg.scope).href,badge:new URL('icons/app-icon-192.png',reg.scope).href,tag:'planner-reminder',data:{url:new URL('./',reg.scope).href}})}catch{}}
