function art(i,cls=''){let label=i==='study-work'?'Рисунок ноутбука для учёбы и работы':artName(i),iconFiles={37:'pickup-ozon.svg',38:'pickup-wildberries.svg',39:'pickup-yandex.svg',40:'doodle-pay-credit-v2.png',41:'doodle-pay-utilities-v2.png',50:'doodle-shoe-wash.png',51:'doodle-ironing.png',52:'doodle-steamer.png',53:'doodle-dog-walk.png',54:'doodle-pharmacy.png',55:'doodle-vet-pharmacy.png',56:'doodle-vet-visit.png',57:'doodle-birthday-v2.png',58:'doodle-hair-color-v2.png',59:'doodle-salon-v2.png',60:'doodle-massage-v2.png',61:'doodle-workout-v2.png',62:'doodle-stretching-v2.png',63:'doodle-trash.png',64:'doodle-vacuum.png',65:'doodle-mop-floor.png',66:'doodle-change-bedding.png',67:'doodle-shower.png',68:'doodle-wash-hair.png',69:'doodle-guinea-pig-hay-water.png',70:'doodle-doctor-visit.png',71:'doodle-return-purchase.png',72:'doodle-feed-cat.png',73:'doodle-date.png',74:'doodle-cat-litter.png',75:'doodle-pet-fresh-water.png',76:'doodle-brush-cat.png',77:'doodle-wash-pet-bowls.png',78:'doodle-change-towels.png',79:'doodle-clean-windows.png',80:'doodle-organize-wardrobe.png',81:'doodle-organize-medicine-cabinet.png'};if(iconFiles[Number(i)])return `<img class="art ${Number(i)>=37&&Number(i)<=41?'pickup-art ':''}${cls}" alt="${label}" src="assets/doodles/${iconFiles[Number(i)]}?v=${Number(i)===40||Number(i)===41||(Number(i)>=57&&Number(i)<=71)||(Number(i)>=73&&Number(i)<=81)?'2':'1'}">`;if(Number(i)>=25&&Number(i)<=36){let cell=Number(i)-25;return `<span class="art art-sprite ${cls}" role="img" aria-label="${label}" style="--sprite-x:${(cell%4)*100/3}%;--sprite-y:${Math.floor(cell/4)*50}%"></span>`}if(Number(i)>=42&&Number(i)<=49){let cell=Number(i)-42;return `<span class="art art-sprite-selfcare ${cls}" role="img" aria-label="${label}" style="--sprite-x:${(cell%4)*100/3}%;--sprite-y:${Math.floor(cell/4)*100}%"></span>`}let src=i==='study-work'?'assets/doodles/doodle-study-work-v2.png?v=2':`assets/doodles/doodle-${i}.png?v=${Number(i)<12?7:1}`;return `<img class="art ${cls}" alt="${label}" src="${src}">`}
function tasksHtml(items){if(!items.length)return `<div class="empty">${art(1,'art-inline')}<br>Пока здесь тихо и уютно</div>`;return items.map(t=>{let legacy={'💧':5,'☀️':6,'📖':7,'📚':7,'🌙':8,'🌼':1,'🧘':9,'💗':3,'✍️':7,'study-work':'study-work'};let icon=Number.isInteger(t.icon)?t.icon:(legacy[t.icon]??1),hasReminder=state.reminders.items.some(x=>String(x.taskId)===String(t.id)&&x.date===state.selectedDate),opened=String(openTaskSwipeId)===String(t.id),hasNote=Boolean(t.note?.trim());return `<div class="task-swipe ${opened?'is-open':''}" data-task-swipe="${t.id}"><button class="task-swipe-delete" data-delete-task="${t.id}" aria-label="Удалить задачу: ${esc(t.name)}" aria-hidden="${opened?'false':'true'}" ${opened?'':'inert'}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v6m4-6v6"/></svg><span>Удалить</span></button><div class="task-swipe-content ${String(t.id)===String(celebrateTaskId)?'task celebrating':'task'}" tabindex="0" role="group" aria-label="Задача: ${esc(t.name)}"><button class="check ${t.done?'done':''}" data-toggle="${t.id}" aria-label="${t.done?'Отменить':'Выполнить'} задачу">${t.done?'✓':''}</button>${art(icon,'task-art')}<span class="task-name ${t.done?'done':''}">${esc(t.name)}${hasNote?'<span class="task-note-indicator" aria-hidden="true"> · заметка</span>':''}</span><span class="task-reward">+${t.reward} <span class="heart">♡</span></span><button class="task-reminder ${hasReminder?'is-set':''}" data-task-reminder="${t.id}" aria-label="${hasReminder?'Изменить':'Добавить'} напоминание: ${esc(t.name)}"><svg viewBox="0 0 32 36" aria-hidden="true"><path d="M8 24c2-3 2-5 2-10a6 6 0 0 1 12 0c0 5 0 7 2 10l2 2H6l2-2Z"/><path d="M13 29c1 4 5 4 6 0M5 13c0-3 1-5 3-7M27 13c0-3-1-5-3-7"/><path class="bell-heart" d="M15 8c-2-2-4 1-1 3l2 2 2-2c3-2 1-5-1-3l-1 1-1-1Z"/></svg></button></div></div>`}).join('')}
function bindTaskSwipes(){const rows=[...document.querySelectorAll('[data-task-swipe]')];const close=()=>{if(openTaskSwipeId!==null){openTaskSwipeId=null;render()}};for(const row of rows){const content=row.querySelector('.task-swipe-content');let startX=0,startY=0,tracking=false;content.addEventListener('click',e=>{if(e.target.closest('button'))return;openTaskNotes(row.dataset.taskSwipe)});content.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;startX=e.clientX;startY=e.clientY;tracking=true});content.addEventListener('pointerup',e=>{if(!tracking)return;tracking=false;const dx=e.clientX-startX,dy=e.clientY-startY;if(Math.abs(dx)<34||Math.abs(dx)<Math.abs(dy)*1.25)return;const id=row.dataset.taskSwipe;if(dx<0){openTaskSwipeId=id;render()}else if(String(openTaskSwipeId)===String(id))close()});content.addEventListener('pointercancel',()=>tracking=false);content.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('button')){e.preventDefault();openTaskNotes(row.dataset.taskSwipe)}else if(e.key==='ArrowLeft'){e.preventDefault();openTaskSwipeId=row.dataset.taskSwipe;render();document.querySelector('[data-delete-task="'+row.dataset.taskSwipe+'"]')?.focus()}else if(e.key==='Escape'||e.key==='ArrowRight'){if(String(openTaskSwipeId)===row.dataset.taskSwipe){e.preventDefault();close()}}});row.querySelector('[data-delete-task]').onclick=()=>deleteTask(row.dataset.taskSwipe)}if(!document.__taskSwipeOutsideBound){document.__taskSwipeOutsideBound=true;document.addEventListener('pointerdown',e=>{if(openTaskSwipeId!==null&&!e.target.closest('[data-task-swipe]')){openTaskSwipeId=null;document.querySelectorAll('[data-task-swipe].is-open').forEach(r=>{r.classList.remove('is-open');const b=r.querySelector('[data-delete-task]');b?.setAttribute('aria-hidden','true');b?.setAttribute('inert','')})}})}}
function deleteTask(id){const tasks=currentTasks(),task=tasks.find(t=>String(t.id)===String(id));if(!task)return;state.plans[state.selectedDate]=tasks.filter(t=>String(t.id)!==String(id));state.reminders.items=state.reminders.items.filter(r=>String(r.taskId)!==String(id));openTaskSwipeId=null;save();render();toast('Задача удалена')}
function week(){let d=dateObject(state.selectedDate),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return ['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((n,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);let key=x.toLocaleDateString('sv-SE');return `<button class="day ${key===state.selectedDate?'active':''}" data-select-date="${key}" aria-label="${n}, ${formatDate(key)}">${n}<b>${x.getDate()}</b></button>`}).join('')}
function today(){let tasks=currentTasks(),done=tasks.filter(t=>t.done).length,isToday=state.selectedDate===dateKey;return `<section class="hero"><span class="doodle d1">♡</span><h1>${isToday?'Сегодня':'Мой план'}</h1><div class="cow-hero-marks" aria-hidden="true"><i class="cow-spot"></i><i class="cow-spot"></i></div><button class="calendar-launch" data-action="calendar"><span>▦</span>${formatDate(state.selectedDate)}<i class="cow-spot cow-date-spot" aria-hidden="true"></i><b>›</b></button><div class="week">${week()}</div><div class="hero-flower-wrap"><i class="cow-spot" aria-hidden="true"></i><i class="cow-spot cow-flower-upper-left" aria-hidden="true"></i><i class="cow-spot cow-flower-upper-right" aria-hidden="true"></i>${art(0,'stem-art')}<i class="cow-spot" aria-hidden="true"></i></div><div class="quote">«Ты можешь больше, чем думаешь» ${art(3,'quote-art')}</div></section><div class="cow-section-marks" aria-hidden="true"><i class="cow-spot"></i><i class="cow-spot"></i></div><div class="section-title"><h3>Задачи на ${isToday?'сегодня':formatDate(state.selectedDate,{day:'numeric',month:'long'})}</h3><span class="sub">${done}/${tasks.length}</span></div><section class="card">${tasksHtml(tasks)}<div class="btn-row"><button class="btn small" data-action="add">Добавить задачу ＋</button></div></section><section class="card stats"><div><small>Выполнено</small><strong>${done}/${tasks.length}</strong></div><div><small>Дофамин</small><strong>${state.dopamine} ♡</strong></div><div><small>Серия дней</small><strong>${state.streak} ☀</strong></div></section><div class="hand" style="text-align:center;color:var(--green)">Маленькие шаги — тоже путь ${art(11,'inline-art')}</div>`}
function welcome(){return `<section class="welcome-screen"><span class="welcome-heart heart-a">♡</span><span class="welcome-heart heart-b">♥</span><div class="welcome-flowers">${art(0,'welcome-stem')}${art(1,'welcome-flower')}</div><div class="welcome-copy"><h1>Мой дофаминовый<br>планер <span class="heart">♡</span></h1><p>Приложение, которое помогает не просто успевать, а получать удовольствие от каждого маленького шага.</p></div>${art(2,'welcome-cat')}<div class="welcome-sparkle">✧</div><button class="btn primary welcome-start" data-action="start">Начать　♡</button></section>`}
